// Filter appointments within the upcoming reminder window (default: 24 hours)
const items = $input.all();
const reminderWindowHours = Number($env.REMINDER_WINDOW_HOURS || 24);
const now = new Date();
const windowEnd = new Date(now.getTime() + reminderWindowHours * 60 * 60 * 1000);

const eligible = [];

for (const item of items) {
  const appointments = item.json.data || [];
  for (const appt of appointments) {
    const scheduledTime = new Date(appt.scheduled_at);
    if (scheduledTime > now && scheduledTime <= windowEnd && appt.status === 'scheduled') {
      const dateFormatted = scheduledTime.toLocaleDateString('en-US', {
        weekday: 'long',
        month: 'short',
        day: 'numeric'
      });
      const timeFormatted = scheduledTime.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit'
      });
      eligible.push({
        json: {
          appointment_id: appt.id,
          client_id: appt.client_id,
          scheduled_at: appt.scheduled_at,
          appointment_type: appt.appointment_type,
          location_label: appt.location_label || 'Main Clinic',
          formatted_date: dateFormatted,
          formatted_time: timeFormatted,
          idempotency_key: `appointment-reminder-${appt.id}-${appt.scheduled_at.substring(0, 10)}`
        }
      });
    }
  }
}

return eligible;

// Idempotency Check: verify if an appointment reminder was already sent
const prevNodeData = $('Filter Within Reminder Window').item.json;
const interactionList = $input.first()?.json?.data || [];

const alreadySent = interactionList.some(interaction => {
  if (interaction.interaction_type !== 'appointment_reminder') return false;
  // Check if sent in the last 24 hours
  const interactionTime = new Date(interaction.created_at).getTime();
  const oneDayAgo = Date.now() - (24 * 60 * 60 * 1000);
  return interactionTime > oneDayAgo;
});

if (alreadySent) {
  return []; // Skip duplicate reminder
}

// Construct privacy-conscious reminder text (neutral: no sensitive medical terms, treatment, or diagnosis)
const reminderMessage = `Hello! This is a reminder of your upcoming appointment on ${prevNodeData.formatted_date} at ${prevNodeData.formatted_time} (${prevNodeData.location_label}). If you need to reschedule or need help with transportation, please reply to this message.`;

return [{
  json: {
    ...prevNodeData,
    reminder_text: reminderMessage,
    channel: 'sms',
    direction: 'outgoing',
    interaction_type: 'appointment_reminder'
  }
}];
